WITH flattened AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, attr_value) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, ROUND(AVG(latency_ms), 2) AS avg_latency_ms, COUNT(DISTINCT host) AS distinct_hosts, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN key = 'version' THEN 1 END), 0), 2) AS latency_ms_per_version FROM flattened GROUP BY DATE_TRUNC('HOUR', log_ts) ORDER BY distinct_hosts DESC NULLS LAST;
